package cn.sifangguan.hotelaios.finance;

import cn.sifangguan.hotelaios.shared.audit.AuditWriter;
import cn.sifangguan.hotelaios.shared.context.TenantPrincipal;
import cn.sifangguan.hotelaios.shared.db.TenantDatabaseContext;
import cn.sifangguan.hotelaios.shared.security.AccessPolicy;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.*;
import java.time.*;
import java.util.*;
import static cn.sifangguan.hotelaios.finance.FinanceCashCorrectionModels.*;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;

/** Two-person correction of a cash recording error. Never sends money or deletes bank evidence. */
@Service @Transactional
public class FinanceCashCorrectionService {
 private final NamedParameterJdbcTemplate jdbc;private final TenantDatabaseContext db;private final AccessPolicy access;private final AuditWriter audit;private final FinanceAccountingService accounting;
 public FinanceCashCorrectionService(NamedParameterJdbcTemplate jdbc,TenantDatabaseContext db,AccessPolicy access,AuditWriter audit,FinanceAccountingService accounting){this.jdbc=jdbc;this.db=db;this.access=access;this.audit=audit;this.accounting=accounting;}
 public Map<String,Object> list(){var p=prepare("finance.read","finance.review","finance.pay");var items=jdbc.queryForList("select c.* from fx_cash_correction c where c.tenant_id=:tenant and "+scope("c")+" and (c.source_kind<>'OPERATION' or exists(select 1 from fo_document d where d.tenant_id=c.tenant_id and d.id=c.document_id and (d.type<>'PAYROLL' or :payroll) and (d.type<>'TAX_TASK' or :tax))) order by c.created_at desc,c.id limit 201",params(p));return Map.of("items",items.stream().limit(200).map(FinanceV2Support::output).toList(),"complete",items.size()<=200);}
 public Map<String,Object> facts(){var p=prepare("finance.read","finance.review","finance.pay");String sql="select y.id,'CLAIM' source_kind,c.id document_id,c.hotel_id,c.company_id,c.title,c.version source_version,'PAYMENT' action,y.paid_on occurred_on,y.amount,y.reference,fx_cash_effective_amount(y.tenant_id,'CLAIM',y.id,y.amount,:asof) effective_amount,fx_bank_instruction_matched_amount(y.tenant_id,y.request_id,:asof) matched_amount from finance_payment y join finance_claim c on c.tenant_id=y.tenant_id and c.id=y.claim_id where y.tenant_id=:tenant and "+scope("c")+" and not exists(select 1 from fc_claim_loan_clear l where l.tenant_id=y.tenant_id and l.payment_id=y.id) union all select a.id,'OPERATION',d.id,d.hotel_id,d.company_id,d.title,d.version,a.action,a.occurred_on,a.amount,a.reference,fx_cash_effective_amount(a.tenant_id,'OPERATION',a.id,a.amount,:asof),fx_bank_action_matched_amount(a.tenant_id,a.id,:asof) from fo_action a join fo_document d on d.tenant_id=a.tenant_id and d.id=a.document_id where a.tenant_id=:tenant and a.action in ('PAYMENT','RECEIPT','REFUND','REPAYMENT') and "+scope("d")+" and (d.type<>'PAYROLL' or :payroll) and (d.type<>'TAX_TASK' or :tax) order by occurred_on desc,id limit 201";var rows=jdbc.queryForList(sql,params(p));return Map.of("items",rows.stream().limit(200).map(FinanceV2Support::output).toList(),"complete",rows.size()<=200,"meaning","原正额收付与净有效金额；差错更正不是执行真实退款，借款抵报销非现金核销不在此入口");}
 public Map<String,Object> detail(UUID correction){var p=prepare("finance.read","finance.review","finance.pay");var row=load(p,correction,false);scopeSource(p,row);var out=output(row);out.put("bankReversals",jdbc.queryForList("select * from fx_bank_match_reversal where tenant_id=:tenant and correction_id=:id order by id",base(p).addValue("id",correction)).stream().map(FinanceV2Support::output).toList());out.put("externalExecution","NONE");return out;}
 public Map<String,Object> request(Request in){var p=prepare("finance.pay","finance.review");lock(p,"request:"+in.requestId());var old=jdbc.queryForList("select * from fx_cash_correction where tenant_id=:tenant and id=:id",base(p).addValue("id",in.requestId()));String requestHash=FinanceService.hash(json(in));if(!old.isEmpty()){scopeSource(p,old.getFirst());if(!p.actorId().equals(old.getFirst().get("created_by"))||!requestHash.equals(old.getFirst().get("request_hash")))throw conflict("差错请求编号已用于其他内容");return detail(in.requestId());}var fact=source(p,in.sourceKind(),in.sourceId(),true);versionSource(fact,in.expectedSourceVersion());var cfg=config(p,id(fact.get("hotel_id")));reviewer(p,cfg,in.reviewerId(),fact);validate(p,fact,in.sourceKind(),in.amount(),in.accountingDate(),in.matchingReversals());var original=original(p,fact,in.sourceKind());var snapshot=new LinkedHashMap<String,Object>();snapshot.put("source",output(fact));snapshot.put("effectiveBefore",effective(p,in.sourceKind(),in.sourceId(),amount(fact.get("amount"))));snapshot.put("matchedBefore",matched(p,in.sourceKind(),fact));snapshot.put("originalSource",output(original));snapshot.put("meaning","更正原资金登记差错，不是退款、不向银行执行、不抹除历史");
  jdbc.update("insert into fx_cash_correction(id,tenant_id,source_kind,source_id,document_id,hotel_id,company_id,original_source_event_id,original_date,accounting_on,original_amount,amount,source_version,source_hash,request_hash,reason,matching_reversals,snapshot,created_by,reviewer_id) values(:id,:tenant,:kind,:source,:doc,:hotel,:company,:event,:originalDate,:day,:original,:amount,:sourceVersion,:sourceHash,:requestHash,:reason,cast(:reversals as jsonb),cast(:snapshot as jsonb),:actor,:reviewer)",base(p).addValue("id",in.requestId()).addValue("kind",in.sourceKind()).addValue("source",in.sourceId()).addValue("doc",fact.get("document_id")).addValue("hotel",fact.get("hotel_id")).addValue("company",fact.get("company_id")).addValue("event",original.get("id")).addValue("originalDate",fact.get("occurred_on")).addValue("day",in.accountingDate()).addValue("original",fact.get("amount")).addValue("amount",money(in.amount())).addValue("sourceVersion",in.expectedSourceVersion()).addValue("sourceHash",sourceHash(fact)).addValue("requestHash",requestHash).addValue("reason",in.reason()).addValue("reversals",json(in.matchingReversals())).addValue("snapshot",json(snapshot)).addValue("reviewer",in.reviewerId()));notifyReview(p,"FINANCE_CASH_ERROR",in.requestId(),in.reviewerId());audit.record("FINANCE_CASH_ERROR_REQUESTED","FINANCE_CASH_CORRECTION",in.requestId(),"{}");return detail(in.requestId());
 }
 public Map<String,Object> review(UUID correction,Review in){var p=prepare("finance.review");var row=load(p,correction,true);scopeSource(p,row);if(!p.actorId().equals(row.get("reviewer_id"))||p.actorId().equals(row.get("created_by")))throw conflict("当前身份不是冻结的独立差错审核人");if(!"REVIEW".equals(row.get("status"))){if(((Number)row.get("version")).intValue()==in.expectedVersion()+1&&p.actorId().equals(row.get("reviewed_by"))&&Objects.equals(row.get("review_note"),in.note())&&(in.approve()?"CONFIRMED":"REJECTED").equals(row.get("status")))return detail(correction);throw conflict("差错已处理，不能重复改变结果");}version(row,in.expectedVersion());var fact=source(p,row.get("source_kind").toString(),id(row.get("source_id")),true);var cfg=config(p,id(fact.get("hotel_id")));reviewerIdentity(cfg,p.actorId(),fact);if(in.approve()){versionSource(fact,((Number)row.get("source_version")).intValue());if(!sourceHash(fact).equals(row.get("source_hash")))throw conflict("原资金或业务版本已变化，须重新申请，不得审核旧快照");var frozen=map(row.get("snapshot"));if(effective(p,row.get("source_kind").toString(),id(row.get("source_id")),amount(fact.get("amount"))).compareTo(amount(frozen.get("effectiveBefore")))!=0||matched(p,row.get("source_kind").toString(),fact).compareTo(amount(frozen.get("matchedBefore")))!=0)throw conflict("资金净额或银行匹配已变化，须重新核对并申请");var reversals=rows(row.get("matching_reversals")).stream().map(r->new MatchReverse(id(r.get("matchId")),amount(r.get("amount")))).toList();validate(p,fact,row.get("source_kind").toString(),amount(row.get("amount")),LocalDate.parse(row.get("accounting_on").toString()),reversals);original(p,fact,row.get("source_kind").toString());for(var r:reversals)jdbc.update("insert into fx_bank_match_reversal(tenant_id,source_kind,match_id,correction_id,amount,accounting_on,created_by) values(:tenant,:kind,:match,:correction,:amount,:day,:actor)",base(p).addValue("kind",row.get("source_kind")).addValue("match",r.matchId()).addValue("correction",correction).addValue("amount",money(r.amount())).addValue("day",row.get("accounting_on")));}
  jdbc.update("update fx_cash_correction set status=:status,reviewed_by=:actor,review_note=:note,reviewed_at=now(),version=version+1 where tenant_id=:tenant and id=:id",base(p).addValue("id",correction).addValue("status",in.approve()?"CONFIRMED":"REJECTED").addValue("note",in.note()));if(in.approve()){var metadata=new LinkedHashMap<String,String>();metadata.put("businessTable","fx_cash_correction");metadata.put("businessId",correction.toString());metadata.put("companyId",row.get("company_id").toString());metadata.put("originalSourceEventId",row.get("original_source_event_id").toString());metadata.put("sourceKind",row.get("source_kind").toString());metadata.put("sourceId",row.get("source_id").toString());metadata.put("documentId",row.get("document_id").toString());metadata.put("originalAction",fact.get("action").toString());metadata.put("sourceType","OPERATION".equals(row.get("source_kind"))?"FO_"+fact.get("document_type"):"REIMBURSEMENT_PAYMENT");accounting.recordSourceEvent(id(row.get("hotel_id")),"FX_CASH_CORRECTION",correction,row.get("source_kind")+"_"+fact.get("action")+"_CORRECTION",LocalDate.parse(row.get("original_date").toString()),LocalDate.parse(row.get("accounting_on").toString()),amount(row.get("amount")),"独立审核原资金登记差错冲回（不执行银行退款）",metadata);}audit.record(in.approve()?"FINANCE_CASH_ERROR_CONFIRMED":"FINANCE_CASH_ERROR_REJECTED","FINANCE_CASH_CORRECTION",correction,json(Map.of("note",in.note())));return detail(correction);
 }
 private Map<String,Object> source(TenantPrincipal p,String kind,UUID source,boolean locked){String sql;if(kind.equals("CLAIM"))sql="select y.*,c.id document_id,c.hotel_id,c.company_id,c.version source_version,c.title,c.applicant_id,c.status document_status,'PAYMENT' action,'CLAIM' document_type,y.paid_on occurred_on from finance_payment y join finance_claim c on c.tenant_id=y.tenant_id and c.id=y.claim_id where y.tenant_id=:tenant and y.id=:id";else if(kind.equals("OPERATION"))sql="select a.*,d.hotel_id,d.company_id,d.version source_version,d.title,d.applicant_id,d.status document_status,d.type document_type,d.details from fo_action a join fo_document d on d.tenant_id=a.tenant_id and d.id=a.document_id where a.tenant_id=:tenant and a.id=:id and a.action in ('PAYMENT','RECEIPT','REFUND','REPAYMENT')";else throw bad("未知资金事实类型");var list=jdbc.queryForList(sql,base(p).addValue("id",source));if(list.isEmpty())throw missing();var fact=list.getFirst();access.requireOrgScope(id(fact.get("hotel_id")));sensitive(fact);if(locked){String table=kind.equals("CLAIM")?"finance_claim":"fo_document";jdbc.queryForList("select id from "+table+" where tenant_id=:tenant and id=:doc for update",base(p).addValue("doc",fact.get("document_id")));fact=jdbc.queryForMap(sql,base(p).addValue("id",source));}if(fact.get("company_id")==null||!"APPROVED".equals(fact.get("document_status")))throw conflict("原业务未批准或主体未冻结，不能按已发生资金冲回");if(kind.equals("CLAIM")&&jdbc.queryForObject("select count(*) from fc_claim_loan_clear where tenant_id=:tenant and payment_id=:id",base(p).addValue("id",source),Integer.class)>0)throw conflict("借款抵报销属于非现金核销，请先办理关联核销的独立调整，不能伪装现金差错");return fact;}
 private void validate(TenantPrincipal p,Map<String,Object> fact,String kind,BigDecimal correction,LocalDate day,List<MatchReverse> reversals){money(correction);if(correction.signum()<=0)throw bad("更正金额必须为正精确分值");LocalDate original=LocalDate.parse(fact.get("occurred_on").toString());if(day.isBefore(original)||day.isAfter(today()))throw bad("更正记账日须不早于原业务日且不晚于今天");jdbc.queryForList("select pg_advisory_xact_lock(hashtextextended(:key,89))",Map.of("key",p.tenantId()+":bank-match"));for(var book:jdbc.queryForList("select id from fa_book where tenant_id=:tenant and hotel_id=:hotel and enabled order by id",base(p).addValue("hotel",fact.get("hotel_id"))))jdbc.queryForList("select pg_advisory_xact_lock(hashtextextended(:key,0))",Map.of("key",p.tenantId()+":book:"+book.get("id")));if(jdbc.queryForObject("select count(*) from fa_period p join fa_book b on b.tenant_id=p.tenant_id and b.id=p.book_id where b.tenant_id=:tenant and b.hotel_id=:hotel and b.enabled and p.month=:month and p.status='CLOSED'",base(p).addValue("hotel",fact.get("hotel_id")).addValue("month",YearMonth.from(day).atDay(1)),Integer.class)>0)throw conflict("更正记账期间已锁定，须选择当前开放日，不得回写旧期间");BigDecimal effective=effective(p,kind,id(fact.get("id")),amount(fact.get("amount")));if(correction.compareTo(effective)>0)throw conflict("累计差错冲回超过原资金净有效金额");if(kind.equals("OPERATION"))dependencies(p,fact,correction);BigDecimal matched=matched(p,kind,fact),undo=BigDecimal.ZERO;Set<UUID> ids=new HashSet<>();for(var r:reversals){if(!ids.add(r.matchId()))throw bad("匹配逆向编号重复");money(r.amount());if(r.amount().signum()<=0)throw bad("匹配逆向金额须为正");String table=kind.equals("CLAIM")?"fc_claim_bank_match":"fo_bank_match",column=kind.equals("CLAIM")?"instruction_id":"action_id";Object sourceId=kind.equals("CLAIM")?fact.get("request_id"):fact.get("id");var matches=jdbc.queryForList("select fx_bank_match_effective_amount(tenant_id,:kind,id,amount,:asof) effective from "+table+" where tenant_id=:tenant and id=:match and "+column+"=:source",params(p).addValue("kind",kind).addValue("match",r.matchId()).addValue("source",sourceId));if(matches.size()!=1||r.amount().compareTo(amount(matches.getFirst().get("effective")))>0)throw conflict("匹配逆向不属于原资金事实或超过净有效分配");undo=undo.add(r.amount());}BigDecimal required=matched.subtract(effective.subtract(correction)).max(BigDecimal.ZERO);if(undo.compareTo(required)<0||undo.compareTo(correction.min(matched))>0)throw conflict("已匹配金额须明确匹配逆向，至少 "+required.toPlainString()+"，最多 "+correction.min(matched).toPlainString()+"；不能删除原匹配");}
 private void dependencies(TenantPrincipal p,Map<String,Object> fact,BigDecimal correction){UUID doc=id(fact.get("document_id"));String type=fact.get("document_type").toString(),action=fact.get("action").toString();BigDecimal payment=actionAmount(p,doc,"PAYMENT"),refund=actionAmount(p,doc,"REFUND"),receipt=actionAmount(p,doc,"RECEIPT");if(action.equals("PAYMENT"))payment=payment.subtract(correction);if(action.equals("REFUND"))refund=refund.subtract(correction);if(action.equals("RECEIPT"))receipt=receipt.subtract(correction);if((type.equals("REVENUE")?receipt:payment).subtract(refund).signum()<0)throw conflict("原现金已被后续退款使用，须先核对并受控调整关联事实");if(action.equals("PAYMENT")&&type.equals("LOAN")&&payment.compareTo(actionAmount(p,doc,"REPAYMENT").add(actionAmount(p,doc,"WRITEOFF")))<0)throw conflict("借款已被还款或报销核销使用，不能直接冲回已清偿资金");if(action.equals("PAYMENT")&&Set.of("ASSET","PREPAYMENT").contains(type)){BigDecimal allocated=actionAmount(p,doc,"DEPRECIATE").add(actionAmount(p,doc,"AMORTIZE")).add(jdbc.queryForObject("select coalesce(sum(r.amount),0) from fa_recurring_run r join fa_recurring_plan p on p.tenant_id=r.tenant_id and p.id=r.plan_id where r.tenant_id=:tenant and p.source_id=:id",base(p).addValue("id",doc),BigDecimal.class));if(payment.subtract(refund).compareTo(allocated)<0)throw conflict("资金已被折旧/摊销使用，须先独立调整下游计提，不能直接冲回");}if(action.equals("REFUND")){BigDecimal approved=jdbc.queryForObject("select amount from fo_document where tenant_id=:tenant and id=:id",base(p).addValue("id",doc),BigDecimal.class);if((type.equals("REVENUE")?receipt:payment).subtract(refund).compareTo(approved)>0)throw conflict("后续替代收付已占用原退款释放额度，须先独立核对，不能恢复超额资金");}}
 private Map<String,Object> original(TenantPrincipal p,Map<String,Object> fact,String kind){String key=kind.equals("CLAIM")?"PAID":fact.get("action").toString();var rows=jdbc.queryForList("select s.* from fa_source_event s left join fa_voucher v on v.tenant_id=s.tenant_id and v.id=s.voucher_id where s.tenant_id=:tenant and s.source_id=:request and s.event_key=:key and s.hotel_id=:hotel and s.amount=:amount and (v.reversed_by_id is null) and ((:kind='CLAIM' and s.source_type='REIMBURSEMENT_PAYMENT') or (:kind='OPERATION' and s.source_type like 'FO_%'))",base(p).addValue("request",fact.get("request_id")).addValue("key",key).addValue("hotel",fact.get("hotel_id")).addValue("amount",fact.get("amount")).addValue("kind",kind));if(rows.size()!=1)throw conflict("原资金会计来源事件缺失、不唯一或原凭证已独立冲销，须先核对，不得无依据更正");return rows.getFirst();}
 private BigDecimal actionAmount(TenantPrincipal p,UUID doc,String action){return jdbc.queryForObject("select fx_operation_action_amount(:tenant,:doc,:action,:asof)",params(p).addValue("doc",doc).addValue("action",action),BigDecimal.class);}
 private BigDecimal effective(TenantPrincipal p,String kind,UUID source,BigDecimal original){return jdbc.queryForObject("select fx_cash_effective_amount(:tenant,:kind,:source,:original,:asof)",params(p).addValue("kind",kind).addValue("source",source).addValue("original",original),BigDecimal.class);}
 private BigDecimal matched(TenantPrincipal p,String kind,Map<String,Object> fact){return jdbc.queryForObject(kind.equals("CLAIM")?"select fx_bank_instruction_matched_amount(:tenant,:id,:asof)":"select fx_bank_action_matched_amount(:tenant,:id,:asof)",params(p).addValue("id",kind.equals("CLAIM")?fact.get("request_id"):fact.get("id")),BigDecimal.class);}
 private Map<String,Object> config(TenantPrincipal p,UUID hotel){var rows=jdbc.queryForList("select * from finance_store_config where tenant_id=:tenant and hotel_id=:hotel and enabled and workflow_version=2",base(p).addValue("hotel",hotel));if(rows.size()!=1)throw conflict("门店主体及独立财务审核配置未发布");return rows.getFirst();}
 private void reviewer(TenantPrincipal p,Map<String,Object> cfg,UUID reviewer,Map<String,Object> fact){if(reviewer.equals(p.actorId()))throw bad("编制人不能审核自己的差错申请");reviewerIdentity(cfg,reviewer,fact);if(jdbc.queryForObject("select count(*) from user_account where tenant_id=:tenant and id=:id and status='ACTIVE'",base(p).addValue("id",reviewer),Integer.class)!=1)throw bad("指定独立审核人账号不可用");}
 private void reviewerIdentity(Map<String,Object> cfg,UUID reviewer,Map<String,Object> fact){if(!Objects.equals(cfg.get("company_id"),fact.get("company_id")))throw conflict("财务主体已调整，须核对旧主体后办理，不可静默迁移资金");if((!Objects.equals(cfg.get("finance_account_id"),reviewer)&&!Objects.equals(cfg.get("director_account_id"),reviewer))||reviewer.equals(fact.get("actor_id"))||reviewer.equals(fact.get("applicant_id")))throw conflict("审核人须为已配置财务/财务总监，且不是原资金登记人或报销申请人");}
 private Map<String,Object> load(TenantPrincipal p,UUID id,boolean lock){var rows=jdbc.queryForList("select * from fx_cash_correction where tenant_id=:tenant and id=:id"+(lock?" for update":""),base(p).addValue("id",id));if(rows.isEmpty())throw missing();return rows.getFirst();}
 private void scopeSource(TenantPrincipal p,Map<String,Object> row){access.requireOrgScope(id(row.get("hotel_id")));if("OPERATION".equals(row.get("source_kind"))){var d=jdbc.queryForMap("select type document_type from fo_document where tenant_id=:tenant and id=:id",base(p).addValue("id",row.get("document_id")));sensitive(d);}}
 private void sensitive(Map<String,Object> fact){if("PAYROLL".equals(fact.get("document_type")))access.requirePermission("finance.payroll");if("TAX_TASK".equals(fact.get("document_type")))access.requirePermission("finance.tax");}
 private void versionSource(Map<String,Object> fact,int expected){if(((Number)fact.get("source_version")).intValue()!=expected)throw conflict("原业务版本已变化，请刷新真实资金事实后重新申请");}
 private String sourceHash(Map<String,Object> fact){return FinanceService.hash(json(output(fact)));}
 private MapSqlParameterSource params(TenantPrincipal p){return base(p).addValue("asof",today()).addValue("payroll",p.hasPermission("*")||p.hasPermission("finance.payroll")).addValue("tax",p.hasPermission("*")||p.hasPermission("finance.tax"));}
 private static String scope(String alias){return "(:tenantScope or "+alias+".hotel_id in (:scopes))";}
 private void notifyReview(TenantPrincipal p,String type,UUID source,UUID recipient){jdbc.update("insert into notification(tenant_id,recipient_account_id,notification_type,title,content,source_type,source_id,idempotency_key) values(:tenant,:recipient,\'FINANCE_REVIEW_PENDING\',\'财务业务待独立核对\',\'有一笔财务业务等待独立核对原件、冻结来源及当前配置。消息不含敏感明细；以实时身份和权限节点为准。\',:type,:source,:key) on conflict(tenant_id,recipient_account_id,idempotency_key) do nothing",base(p).addValue("recipient",recipient).addValue("type",type).addValue("source",source).addValue("key",type+":"+source+":REVIEW:0:"+recipient));}
 private TenantPrincipal prepare(String... permissions){access.requireAnyPermission(permissions);var p=access.principal();db.apply(p.tenantId());return p;}
 private void lock(TenantPrincipal p,String key){jdbc.queryForList("select pg_advisory_xact_lock(hashtextextended(:key,98))",Map.of("key",p.tenantId()+":"+key));}
 private static LocalDate today(){return LocalDate.now(ZoneId.of("Asia/Shanghai"));}
 private static BigDecimal money(BigDecimal n){try{var value=n.setScale(2,RoundingMode.UNNECESSARY);if(value.precision()>18)throw new ArithmeticException();return value;}catch(Exception e){throw bad("金额须为不超过18位的精确分值，不接受隐式四舍五入");}}
}
